 let bg=g.createLinearGradient(0,0,960,540);bg.addColorStop(0,'#405237');bg.addColorStop(.52,'#34452f');bg.addColorStop(1,'#293c2c');g.fillStyle=bg;g.fillRect(0,0,960,540);
 // ground mottling
 for(let i=0;i<130;i++){let x=(i*173+42)%960,y=(i*97+21)%540;g.fillStyle=i%3?'#8a9b5b0b':'#d2d69b09';g.beginPath();g.ellipse(x,y,22+(i%7)*3,8+(i%5)*2,(i*.7)%3,0,Math.PI*2);g.fill()}
 // forest edging and decorative trees
 for(const d of mapDecor){g.fillStyle=d.kind>.54?'#1e3228':'#536047';g.beginPath();g.ellipse(d.x+2,d.y+5,d.r*1.1,d.r*.55,0,0,Math.PI*2);g.fill();g.fillStyle=d.kind>.54?'#253d2d':'#596749';g.beginPath();g.arc(d.x,d.y,d.r,0,Math.PI*2);g.fill();g.fillStyle='#a1a46b19';g.beginPath();g.arc(d.x-d.r*.28,d.y-d.r*.3,d.r*.54,0,Math.PI*2);g.fill()}
 // route shadow and worn road
 g.lineCap='round';g.lineJoin='round';g.beginPath();path.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.strokeStyle='#18221b';g.lineWidth=86;g.stroke();g.strokeStyle='#807c58';g.lineWidth=72;g.stroke();g.strokeStyle='#a49a6d';g.lineWidth=62;g.stroke();g.strokeStyle='#b9aa7750';g.lineWidth=2;g.setLineDash([3,14]);g.stroke();g.setLineDash([]);
 // road stones / grass detail
 for(let i=0;i<150;i++){let p=((i*73)%1000)/1000,pt=pathPoint(p),side=(i%2?1:-1)*(20+(i*17)%10),x=pt.x+side,y=pt.y+((i*37)%28-14);g.fillStyle=i%3?'#514f3e':'#c3b48748';g.beginPath();g.ellipse(x,y,2+(i%3),1.5,0,0,Math.PI*2);g.fill()}
 // map boundary marks
 g.strokeStyle='#d5c48a18';g.lineWidth=1;g.strokeRect(10,10,940,520);
 // entrance / keep
 drawGate(28,280,false);drawGate(925,300,true);
 // build circles
