 // hero and tower ranges
 if(state.selectedTower){let t=state.selectedTower,d=towerDefs.find(a=>a.type===t.type);g.fillStyle=d.color+'14';g.strokeStyle=d.color+'77';g.lineWidth=2;g.beginPath();g.arc(t.x,t.y,d.range+(t.level-1)*12,0,Math.PI*2);g.fill();g.stroke()}
 if(state.selectedType){let m=mouseMap;if(m){let d=towerDefs.find(a=>a.type===state.selectedType),ok=validBuild(m.x,m.y);g.fillStyle=(ok?'#d8c46b':'#d86f5b')+'22';g.strokeStyle=(ok?'#ead478':'#e17d68')+'aa';g.setLineDash([5,4]);g.beginPath();g.arc(m.x,m.y,d.range,0,Math.PI*2);g.fill();g.stroke();g.setLineDash([])}}
 state.towers.forEach(drawTower);state.enemies.forEach(drawEnemy);drawHero();state.projectiles.forEach(drawProjectile);state.particles.forEach(drawParticle);
