}
function drawGate(x,y,keep){let g=ctx;g.save();g.translate(x,y);if(keep){g.fillStyle='#151f19';g.fillRect(-18,-31,37,62);g.fillStyle='#66553a';g.fillRect(-14,-29,27,56);g.fillStyle='#a88c59';g.fillRect(-15,-35,7,9);g.fillRect(8,-35,7,9);g.fillStyle='#d8c982';g.beginPath();g.arc(0,-5,4,0,Math.PI*2);g.fill();g.fillStyle='#d8b558';g.font='bold 8px Cinzel';g.textAlign='center';g.fillText('KEEP',0,43)}else{g.fillStyle='#4d5134';g.fillRect(-5,-28,10,56);g.fillStyle='#926f3e';g.fillRect(-20,-29,40,7);g.fillRect(-20,22,40,7);g.fillStyle='#c2a15c';g.beginPath();g.moveTo(-20,-30);g.lineTo(-14,-39);g.lineTo(-8,-30);g.lineTo(0,-39);g.lineTo(8,-30);g.lineTo(14,-39);g.lineTo(20,-30);g.fill();g.fillStyle='#d7cf9f';g.font='bold 8px Cinzel';g.textAlign='center';g.fillText('DARKWOOD',0,46)}g.restore()}
function drawTower(t){let g=ctx,d=towerDefs.find(a=>a.type===t.type),r=15+(t.level-1);g.save();g.translate(t.x,t.y);g.fillStyle='#151a13aa';g.beginPath();g.ellipse(2,8,19,10,0,0,Math.PI*2);g.fill();g.fillStyle='#515442';g.beginPath();g.arc(0,0,r+3,0,Math.PI*2);g.fill();g.fillStyle='#282d24';g.beginPath();g.arc(0,0,r,0,Math.PI*2);g.fill();g.strokeStyle=d.color;g.lineWidth=2;g.beginPath();g.arc(0,0,r-2,-Math.PI*.8,Math.PI*.8);g.stroke();g.fillStyle=d.color;g.font='16px sans-serif';g.textAlign='center';g.textBaseline='middle';g.fillText(({arrow:'➶',arcane:'✦',frost:'❄',cannon:'◉'})[t.type],0,0);if(t.level>1){g.fillStyle='#eed57e';g.font='bold 9px DM Sans';g.fillText('★'+t.level,0,-r-6)}if(t===state.selectedTower){g.strokeStyle='#f3da8c';g.lineWidth=2;g.beginPath();g.arc(0,0,r+7,0,Math.PI*2);g.stroke()}g.restore()}
function drawEnemy(e){let g=ctx;g.save();g.translate(e.x,e.y);if(e.flash>0)g.globalAlpha=.55+Math.sin(e.flash*30)*.4;let c=e.boss?'#9e4439':['#69814b','#8b6044','#667188','#a28a4f','#805b72'][e.kind];g.fillStyle='#10161199';g.beginPath();g.ellipse(2,e.radius*.8,e.radius*1.2,e.radius*.58,0,0,Math.PI*2);g.fill();g.fillStyle=c;g.beginPath();g.arc(0,0,e.radius,0,Math.PI*2);g.fill();g.fillStyle=e.boss?'#e7c96d':'#d9c9a1';g.beginPath();g.arc(-e.radius*.28,-e.radius*.16,e.radius*.2,0,Math.PI*2);g.arc(e.radius*.28,-e.radius*.16,e.radius*.2,0,Math.PI*2);g.fill();if(e.boss){g.strokeStyle='#d4a84d';g.lineWidth=3;g.beginPath();g.moveTo(-9,-12);g.lineTo(-16,-23);g.moveTo(9,-12);g.lineTo(16,-23);g.stroke()}let bw=e.boss?40:25,ratio=Math.max(0,e.hp/e.maxHp);g.fillStyle='#111';g.fillRect(-bw/2,-e.radius-9,bw,4);g.fillStyle=ratio>.5?'#90b36a':'#d16852';g.fillRect(-bw/2,-e.radius-9,bw*ratio,4);g.restore()}
function drawHero(){let g=ctx,h=state.hero;g.save();g.translate(h.x,h.y);g.fillStyle='#1015109c';g.beginPath();g.ellipse(2,9,16,8,0,0,Math.PI*2);g.fill();g.fillStyle='#6e8a68';g.beginPath();g.arc(0,0,13,0,Math.PI*2);g.fill();g.fillStyle='#d6c68e';g.beginPath();g.arc(0,-3,6,0,Math.PI*2);g.fill();g.fillStyle='#b8c2c7';g.fillRect(7,-8,3,18);g.fillStyle='#eee2b8';g.fillRect(-7,-7,4,12);g.fillStyle='#eccb71';g.beginPath();g.arc(0,-14,3,0,Math.PI*2);g.fill();if(h.hp<h.maxHp){g.fillStyle='#111';g.fillRect(-13,-22,26,3);g.fillStyle='#8cc276';g.fillRect(-13,-22,26*Math.max(0,h.hp/h.maxHp),3)}g.restore()}
function drawProjectile(p){let g=ctx;g.fillStyle=p.color;g.beginPath();g.arc(p.x,p.y,p.r||4,0,Math.PI*2);g.fill();if(p.type==='arcane'||p.type==='frost'){g.globalAlpha=.25;g.beginPath();g.arc(p.x,p.y,(p.r||4)*2.5,0,Math.PI*2);g.fill();g.globalAlpha=1}}
function drawParticle(p){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}

