function drawParticle(p){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
function validBuild(x,y){return x>35&&x<925&&y>35&&y<505&&!nearPath(x,y,49)&&state.towers.every(t=>Math.hypot(t.x-x,t.y-y)>42)}
let mouseMap=null;
function positionFromEvent(e){let r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*960,y:(e.clientY-r.top)/r.height*540}}
canvas.addEventListener('pointermove',e=>{mouseMap=positionFromEvent(e)});
canvas.addEventListener('pointerleave',()=>mouseMap=null);
canvas.addEventListener('pointerdown',e=>{e.preventDefault();let p=positionFromEvent(e);if(state.gameOver)return;
 let hit=[...state.towers].reverse().find(t=>Math.hypot(t.x-p.x,t.y-p.y)<23);if(hit){state.selectedTower=hit;state.selectedType=null;refresh();return}
 if(state.selectedType){let d=towerDefs.find(t=>t.type===state.selectedType);if(state.gold<d.cost){showToast('Not enough gold');return}if(!validBuild(p.x,p.y)){showToast('Choose a clear space beside the road');return}state.gold-=d.cost;state.towers.push({type:d.type,x:p.x,y:p.y,level:1,cooldown:.2,buff:0});state.selectedTower=state.towers[state.towers.length-1];state.selectedType=null;save();refresh();return}
 state.selectedTower=null;refresh()
});
function damageEnemy(e,damage,slow=0){if(!state.enemies.includes(e))return;e.hp-=damage;e.flash=.13;if(slow)e.slow=Math.max(e.slow,slow);if(e.hp<=0){let idx=state.enemies.indexOf(e);if(idx<0)return;state.enemies.splice(idx,1);state.kills++;let reward=(e.boss?42:7)+Math.floor(state.wave*.45);state.gold+=reward;state.xp+=e.boss?22:5;burst(e.x,e.y,e.boss?'#e7be68':'#c3d57d',e.boss?18:8);while(state.xp>=state.heroLevel*30){state.xp-=state.heroLevel*30;state.heroLevel++;state.hero.attack+=5;state.hero.maxHp+=12;state.hero.hp=Math.min(state.hero.maxHp,state.hero.hp+35);showToast('HERO RANK '+state.heroLevel)}save()}}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=rand()*Math.PI*2,s=20+rand()*110;state.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+rand()*.55,max:.9,r:1.5+rand()*2.5,color})}}
